import{_ as t,o as a,c as i,aQ as o}from"./chunks/framework.cDvftfeu.js";const p=JSON.parse(`{"title":"MCP Service","description":"Introduction to Ham MCP service — Connect Ham's capabilities to your AI assistant via MCP.","frontmatter":{"description":"Introduction to Ham MCP service — Connect Ham's capabilities to your AI assistant via MCP.","next":{"text":"Configuration","link":"/en/guide/mcp/config"}},"headers":[],"relativePath":"en/guide/mcp/index.md","filePath":"en/guide/mcp/index.md","lastUpdated":1779798458000}`),n={name:"en/guide/mcp/index.md"};function r(s,e,c,l,d,h){return a(),i("div",null,[...e[0]||(e[0]=[o('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /guide/mcp.md for this page in Markdown format</div><h1 id="mcp-service" tabindex="-1">MCP Service <a class="header-anchor" href="#mcp-service" aria-label="Permalink to &quot;MCP Service&quot;">​</a></h1><p>Ham provides an MCP (Model Context Protocol) service that allows you to connect Ham&#39;s campus data and capabilities to MCP-compatible AI assistants (such as Claude Desktop, Cursor, etc.).</p><h2 id="what-is-mcp" tabindex="-1">What is MCP? <a class="header-anchor" href="#what-is-mcp" aria-label="Permalink to &quot;What is MCP?&quot;">​</a></h2><p>MCP (<a href="https://modelcontextprotocol.io/" target="_blank" rel="noreferrer">Model Context Protocol</a>) is an open protocol that enables AI applications to securely connect to external data sources and tools. Through Ham&#39;s MCP service, your AI assistant can:</p><ul><li>Query course information and grades</li><li>View personal information</li></ul><h2 id="service-url" tabindex="-1">Service URL <a class="header-anchor" href="#service-url" aria-label="Permalink to &quot;Service URL&quot;">​</a></h2><p>Ham MCP service uses <strong>Streamable HTTP</strong> transport:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://mcp.ham.nowcent.cn/mcp</span></span></code></pre></div><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>Ham MCP service supports two authentication methods:</p><ul><li><strong>OAuth Dynamic Registration (recommended)</strong>: The client automatically completes registration and authorization on first connection — no manual API Key creation required. Suitable for modern MCP-OAuth-capable clients (Claude Desktop, Cursor, ChatGPT, Codex, etc.).</li><li><strong>API Key</strong>: Manually generate an API Key in the Ham console and authenticate via the <code>Authorization: Bearer &lt;API_KEY&gt;</code> request header — suitable for clients that do not support OAuth dynamic registration, or when a long-lived credential is needed.</li></ul><h3 id="oauth-dynamic-registration-recommended" tabindex="-1">OAuth Dynamic Registration (recommended) <a class="header-anchor" href="#oauth-dynamic-registration-recommended" aria-label="Permalink to &quot;OAuth Dynamic Registration (recommended)&quot;">​</a></h3><p>Ham MCP service follows the <a href="https://modelcontextprotocol.io/specification/draft/basic/authorization" target="_blank" rel="noreferrer">MCP Authorization specification</a>, implementing <a href="https://datatracker.ietf.org/doc/html/rfc7591" target="_blank" rel="noreferrer">OAuth 2.0 Dynamic Client Registration (RFC 7591)</a> and <a href="https://datatracker.ietf.org/doc/html/rfc9728" target="_blank" rel="noreferrer">Protected Resource Metadata (RFC 9728)</a>.</p><p>The integration flow is fully handled by the client:</p><ol><li>The client requests the service URL and receives a <code>401 Unauthorized</code> response.</li><li>The client discovers the authorization server via <code>/.well-known/oauth-protected-resource</code>.</li><li>The client registers itself dynamically and obtains a <code>client_id</code>.</li><li>The browser opens the Ham authorization page; after sign-in and consent, the user is redirected back.</li><li>The client receives an access token and automatically attaches it to subsequent requests — no manual configuration needed.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>With dynamic registration, you only need to fill in the service URL <code>https://mcp.ham.nowcent.cn/mcp</code> in your client. Everything else is handled automatically.</p></div><h3 id="api-key" tabindex="-1">API Key <a class="header-anchor" href="#api-key" aria-label="Permalink to &quot;API Key&quot;">​</a></h3><p>If your client does not support OAuth dynamic registration, or you prefer a long-lived static credential, generate an API Key in the Ham console and configure it manually.</p><h4 id="getting-an-api-key" tabindex="-1">Getting an API Key <a class="header-anchor" href="#getting-an-api-key" aria-label="Permalink to &quot;Getting an API Key&quot;">​</a></h4><ol><li>Visit <a href="https://ham.nowcent.cn/console/tokens" target="_blank" rel="noreferrer">Ham Console - API Keys</a></li><li>Click &quot;Create API Key&quot;</li><li>Add a description for the API Key (e.g., &quot;Claude Desktop&quot;) for easy management</li><li>Copy the generated API Key (<strong>shown only once, keep it safe</strong>)</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Do not share your API Key with others. An API Key is equivalent to your account credentials — leakage may result in unauthorized access to your personal information.</p></div>',22)])])}const m=t(n,[["render",r]]);export{p as __pageData,m as default};
